import {pounds,GBP_PER_UNIT} from './manager-money.js';
import {FOUNDING_BUDGETS,FUNDING_BENCHMARK} from './club-funding.js';
import {escapeHtml as esc,clubBadge} from './ui-kit.js';
export function founderSetup(custom,clubs){
 const club=clubs.find(p=>p.id===custom.replace)||clubs[0],step=Math.max(0,Math.min(3,custom.step||0)),field=(n,title,content)=>`<fieldset ${n!==step?'hidden':''}><legend>${title}</legend>${content}</fieldset>`;
 return `<ol class="mgr-setup-steps" aria-label="Create a club steps">${['Identity','Competition','Funding','Review'].map((name,i)=>`<li ${i===step?'aria-current="step"':''}><span>${i+1}</span>${name}</li>`).join('')}</ol><div class="create-club-layout mgr-founder-setup"><form id="create-club-form">${field(0,'Give your club an identity',`<p>A name and colours to carry into every fixture.</p><label for="new-club-name">Club name</label><input id="new-club-name" name="name" value="${esc(custom.name)}" required minlength="3" maxlength="32" placeholder="e.g. London Borough FC"><label for="new-club-color">Club colour</label><input id="new-club-color" name="color" type="color" value="${esc(custom.color)}">`)}${field(1,'Choose your place',`<label for="new-club-competition">Career competition</label><select id="new-club-competition" name="league"><option value="english-sandbox" ${custom.league!=='super-league'?'selected':''}>Premier League sandbox</option><option value="super-league" ${custom.league==='super-league'?'selected':''}>Super League</option></select>${new URLSearchParams(globalThis.location?.search||'').has('qa')?`<label><input type="checkbox" name="superPreview" ${custom.superPreview?'checked':''}> Test league + Super Cup rules (Super League only; unverified October squads)</label>`:''}<label for="new-club-replace">Replace a Premier League club</label><select id="new-club-replace" name="replace">${clubs.map(p=>`<option value="${p.id}" ${p.id===custom.replace?'selected':''}>${esc(p.club)}</option>`).join('')}</select><p>Your English club takes one of twenty league places. It begins with eighteen original players, so the replaced club keeps its squad.</p>`)}${field(2,'Fund your football project',`<label for="new-club-budget">Total football funding</label><select id="new-club-budget" name="budget">${FOUNDING_BUDGETS.map(({units,label})=>`<option value="${units}" ${Number(custom.budget)===units?'selected':''}>${label}</option>`).join('')}</select><p>Shared funding pays transfer fees, wages and renewals. Consider retaining £150m for operating costs. Stadium and club purchase costs are outside this sandbox.</p><details><summary>Why £750m?</summary><p>Average Premier League squad acquisition cost: about £563m including possible add-ons. The default leaves room for recruitment and wages. Authored game funding.</p><a href="${FUNDING_BENCHMARK.source}" target="_blank" rel="noopener noreferrer">CIES · September 2026 ↗</a></details>`)}${field(3,'Ready to build your story',`<p><strong>${esc(custom.name)}</strong> · ${custom.league==='super-league'?'Super League':'Premier League sandbox'}</p><p>Replacing ${esc(club.club)} · ${pounds(Number(custom.budget)*GBP_PER_UNIT)} total football funding.</p><p>Your eighteen original players are ready to play. Build the squad now or take them straight into match preparation.</p><p class="stat-foot">Fictional league rules and authored starting ownership. Missing source dates/real loan terms remain unverified; source player dossiers stay separately labelled.</p>`)}<div class="mgr-actions">${step?'<button type="button" class="btn ghost" data-action="eu-setup-back">Back</button>':''}${step<3?'<button type="button" class="btn primary" data-action="eu-setup-next">Continue setup</button>':'<button type="submit" class="btn primary">Create club & start career</button>'}</div></form><aside class="club-preview" style="--club:${custom.color}">${clubBadge(custom.name||'Your club',custom.color)}<span class="eyebrow">YOUR FOOTBALL PROJECT</span><h2>${esc(custom.name||'Your new club')}</h2><p>Replacing ${esc(club.club)} · 20 clubs · 38 matchdays</p><div class="studio-metric"><span>TOTAL FOOTBALL FUNDING</span><strong>${pounds(Number(custom.budget)*GBP_PER_UNIT)}</strong></div><p>18 original starter players · squad building is optional.</p></aside></div>`;
}
